        frame(cx);
        prompt_mode.update(cx, |this, cx| {
            for task in this.tasks.iter_mut().take(10) {
                task.status = TaskStatus::Done;
            }
            cx.notify();
        });
        frame(cx);
        assert_eq!(top_row(cx), before, "the rows in view moved");
    }

